endpoint('pos_drawer',['action'=>'lock','shift_id'=>$pdShift,'request_key'=>$pdKey()]);
$pdPassword=endpoint('pos_drawer',['action'=>'unlock','shift_id'=>$pdShift,'secret'=>'drawer-test-password']);check($pdPassword['success'],'account password can reauthenticate the assigned cashier drawer');
$pdMoveKey=$pdKey();$pdMove=['action'=>'move','shift_id'=>$pdShift,'kind'=>'cash_in','amount'=>'5','notes'=>'POS float top-up','request_key'=>$pdMoveKey];endpoint('pos_drawer',$pdMove);endpoint('pos_drawer',$pdMove);
check(CashShift::detail($pdShift)['totals']['expected_cents']===11500,'in-POS cash movement uses the audited idempotent shift ledger');
$pdStale=endpoint('pos_drawer',['action'=>'close','shift_id'=>$pdShift+999,'amount'=>'115','notes'=>'Stale tab','request_key'=>$pdKey()]);check(!$pdStale['success'] && CashShift::detail($pdShift)['status']==='open','stale modal cannot operate on a different active drawer');
$pdBadCount=endpoint('pos_drawer',['action'=>'close','shift_id'=>$pdShift,'amount'=>'114','notes'=>'','request_key'=>$pdKey()]);check(!$pdBadCount['success'] && CashShift::detail($pdShift)['status']==='open','POS closing modal requires a discrepancy explanation');
$pdClose=endpoint('pos_drawer',['action'=>'close','shift_id'=>$pdShift,'amount'=>'114','notes'=>'One peso short on physical count','request_key'=>$pdKey()]);
check($pdClose['success'] && $pdClose['state']['shift']===null && $pdClose['closing']['expected_cash']==='115.00' && $pdClose['closing']['difference']==='-1.00','POS closing seals the shift and returns its frozen closing summary');
$pdBlocked=endpoint('pos_cart',['action'=>'add','product_id'=>$csProduct]);check(!$pdBlocked['success'],'closed POS drawer cannot be used again until a new opening');
