$_SESSION['user']=['id'=>3,'branch_id'=>2];
reject(function()use($pdShift,$pdKey){CashShift::lockDrawer($pdShift,$pdKey());},'drawer lock operations cannot target another branch or cashier');
$_SESSION['user']=['id'=>1,'branch_id'=>1];
// Render the actual POS partial against the disposable database; no production login is bypassed.
