file_put_contents($root.'/scratch/pos-drawer-rendered.html',$pdHtml);
reject(function()use($csProduct,$pdKey){RecipeInventory::checkout(1,1,[['product_id'=>$csProduct,'quantity'=>1]],'0','10','Cash','Dine-in',$pdKey(),true);},'checkout commit requires a drawer even if the optional branch policy is off');
RecipeInventory::query('UPDATE users SET password=?,pos_pin=? WHERE id=1','ss',[$pdAccount['password'],$pdAccount['pos_pin']]);
$pipes=[];$p=proc_open([PHP_BINARY,$root.'/tools/tests/burger-integration.php','--endpoint',$workspace,'pos_render',base64_encode('{}')],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fclose($pipes[0]);$html=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);proc_close($p);
check(strpos($html,'id="checkoutBtn"')!==false && strpos($html,'id="pos-drawer-dialog"')!==false && !preg_match('/Warning:|Notice:|Fatal error:/',$html.$err),'actual POS page renders its existing checkout and integrated drawer without PHP warnings');
