$pdWrongSource=endpoint('pos_drawer',array_merge($pdReuse,['confirm_cash'=>'1','previous_shift_id'=>$pdShift+999,'request_key'=>$pdKey()]));check(!$pdWrongSource['success'],'previous cash option rejects a different closing reference');
$pdReuse['confirm_cash']='1';$pdReopened=endpoint('pos_drawer',$pdReuse);
check($pdReopened['success'] && $pdReopened['state']['shift']['totals']['opening_cents']===11400,'next shift opens with server-validated actual counted cash');
